package entities

// Role is a named set of permissions assigned to a user.
type Role string

// Permission allows a user to perform one privileged action.
type Permission string

const (
	RoleAdmin Role = "admin"
)

const (
	// PermListUsers allows listing every registered user.
	PermListUsers Permission = "users:list"
	// PermAddSensorByID allows registering a sensor under a caller-chosen ID
	// instead of one generated by the server.
	PermAddSensorByID Permission = "sensors:add_by_id"
)

// rolePermissions is the source of truth for what each role may do. Roles are
// stored per user in the database, permissions are not, so changing a role here
// takes effect for every user holding it.
var rolePermissions = map[Role][]Permission{
	RoleAdmin: {PermListUsers, PermAddSensorByID},
}

// ValidRole reports whether r is a role known to the server.
func ValidRole(r Role) bool {
	_, ok := rolePermissions[r]
	return ok
}

// PermissionsFor returns the union of the permissions granted by roles, without
// duplicates. It never returns nil, so it encodes as an empty JSON array.
func PermissionsFor(roles []Role) []Permission {
	seen := make(map[Permission]struct{})
	perms := []Permission{}
	for _, r := range roles {
		for _, p := range rolePermissions[r] {
			if _, ok := seen[p]; ok {
				continue
			}
			seen[p] = struct{}{}
			perms = append(perms, p)
		}
	}
	return perms
}

// HasPermission reports whether any of roles grants perm.
func HasPermission(roles []Role, perm Permission) bool {
	for _, r := range roles {
		for _, p := range rolePermissions[r] {
			if p == perm {
				return true
			}
		}
	}
	return false
}
